llm_calls.content:
{
  "task_summary": "Predict whether an ACS person is employed, using demographic and household attributes that generalize across states.",
  "ranking": [
    {
      "rank": 1,
      "feature_id": 0,
      "rationale": "Age is the strongest universal driver of labor force attachment and employment probability."
    },
    {
      "rank": 2,
      "feature_id": 1,
      "rationale": "Education is a stable, highly predictive proxy for employability and job access across states."
    },
    {
      "rank": 3,
      "feature_id": 4,
      "rationale": "Disability status strongly affects employment and is semantically meaningful across geographies."
    },
    {
      "rank": 4,
      "feature_id": 14,
      "rationale": "Sex captures broad labor-market participation differences that persist across states, though imperfectly."
    },
    {
      "rank": 5,
      "feature_id": 2,
      "rationale": "Marital status correlates with age, household responsibilities, and employment in a fairly portable way."
    },
    {
      "rank": 6,
      "feature_id": 3,
      "rationale": "Household relationship helps identify dependents, spouses, and household roles tied to employment likelihood."
    },
    {
      "rank": 7,
      "feature_id": 10,
      "rationale": "Nativity can matter for employment through immigration-related barriers, but effects are less direct and more variable."
    },
    {
      "rank": 8,
      "feature_id": 6,
      "rationale": "Citizenship status is related to work eligibility and labor-market access, but may be partly redundant with nativity."
    },
    {
      "rank": 9,
      "feature_id": 15,
      "rationale": "Race can capture persistent structural labor-market disparities, but it is also a demographic shortcut and less causal."
    },
    {
      "rank": 10,
      "feature_id": 9,
      "rationale": "Ancestry may weakly proxy cultural or immigrant-background differences, but it is noisy and less portable."
    },
    {
      "rank": 11,
      "feature_id": 7,
      "rationale": "Recent mobility can reflect life transitions affecting employment, but it is more state- and housing-market-sensitive."
    },
    {
      "rank": 12,
      "feature_id": 8,
      "rationale": "Military service status can relate to employment pathways, but it is niche and not broadly predictive."
    },
    {
      "rank": 13,
      "feature_id": 11,
      "rationale": "Hearing difficulty affects employability, but prevalence and reporting can be noisy and age-confounded."
    },
    {
      "rank": 14,
      "feature_id": 12,
      "rationale": "Vision difficulty is relevant but usually weaker and more indirectly related to employment than core health or age factors."
    },
    {
      "rank": 15,
      "feature_id": 13,
      "rationale": "Cognitive difficulty can matter for employment, but self-report noise and heterogeneity reduce portability."
    },
    {
      "rank": 16,
      "feature_id": 5,
      "rationale": "Employment status of parents is mainly defined for children and is likely a brittle proxy with limited relevance here."
    }
  ]
}
